<?php
namespace Tests\Feature;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Hash;
use Tests\TestCase;
class ApiTest extends TestCase {
use RefreshDatabase;
public function test_api_requires_authentication():void{$this->getJson('/api/v1/students')->assertUnauthorized();}
public function test_api_login_and_logout():void{$user=User::factory()->create(['role'=>'registrar','must_change_password'=>false,'password'=>Hash::make('ApiPassword123!')]);$response=$this->postJson('/api/v1/auth/login',['email'=>$user->email,'password'=>'ApiPassword123!'])->assertOk()->assertJsonPath('role','registrar');$token=$response->json('token');$this->withToken($token)->getJson('/api/v1/students')->assertOk()->assertJsonPath('total',0);$this->withToken($token)->postJson('/api/v1/auth/logout')->assertOk();$this->assertDatabaseCount('personal_access_tokens',0);}
public function test_source_scoped_token_cannot_access_portal_or_other_imports():void{$user=User::factory()->create(['role'=>'registrar','must_change_password'=>false]);$token=$user->createToken('admission',['import:admission'])->plainTextToken;$this->withToken($token)->getJson('/api/v1/students')->assertForbidden();$this->withToken($token)->postJson('/api/v1/integrations/ems',['source'=>'ems','schema_version'=>'1.0','employees'=>[]])->assertForbidden();}
public function test_api_student_cannot_create_subject():void{$user=User::factory()->create(['role'=>'student','must_change_password'=>false]);$token=$user->createToken('portal',['portal'])->plainTextToken;$this->withToken($token)->postJson('/api/v1/subjects',['code'=>'X','name'=>'Unauthorized','units'=>3,'type'=>'lecture','allowed_days'=>'Mon'])->assertForbidden();}
public function test_api_requires_temporary_password_change():void{$user=User::factory()->create(['role'=>'student','must_change_password'=>true,'password'=>Hash::make('TemporaryPass123')]);$token=$user->createToken('portal',['portal'])->plainTextToken;$this->withToken($token)->getJson('/api/v1/students')->assertForbidden();$this->withToken($token)->postJson('/api/v1/auth/change-password',['current_password'=>'TemporaryPass123','password'=>'ChangedApiPassword123','password_confirmation'=>'ChangedApiPassword123'])->assertOk();$this->assertFalse($user->fresh()->must_change_password);$this->assertDatabaseCount('personal_access_tokens',0);}
public function test_ems_api_import_matches_employee_id():void{$user=User::factory()->create(['role'=>'registrar','must_change_password'=>false]);$token=$user->createToken('ems',['import:ems'])->plainTextToken;$payload=['source'=>'ems','schema_version'=>'1.0','employees'=>[['employee_id'=>'API-EMP-1','first_name'=>'Test','last_name'=>'Professor','email'=>'api-prof@example.test','department_code'=>'CCS','employment_type'=>'FULL_TIME','employment_status'=>'ACTIVE']]];for($i=0;$i<2;$i++)$this->withToken($token)->postJson('/api/v1/integrations/ems',$payload)->assertOk()->assertJsonPath('rejected',0);$this->assertDatabaseCount('professors',1);$this->assertDatabaseHas('external_sync_logs',['updated'=>1]);}
public function test_registrar_can_create_subject_through_rest_endpoint():void{$user=User::factory()->create(['role'=>'registrar','must_change_password'=>false]);$token=$user->createToken('portal',['portal'])->plainTextToken;$this->withToken($token)->postJson('/api/v1/subjects',['code'=>'API101','name'=>'API created subject','units'=>3,'type'=>'lecture','allowed_days'=>'Mon,Wed'])->assertCreated();$this->assertDatabaseHas('subjects',['code'=>'API101']);}
public function test_expired_api_token_is_rejected():void{$user=User::factory()->create(['role'=>'registrar','must_change_password'=>false]);$token=$user->createToken('expired',['portal'],now()->subMinute())->plainTextToken;$this->withToken($token)->getJson('/api/v1/students')->assertUnauthorized();}
}
